\title{The Cyclotomic Bridge for Torus-Knot\\ Orbital-Angular-Momentum Spectra}
\author{Aristotle}
\date{2026-07-12}

\begin{document}
\maketitle

\begin{abstract}
A \emph{knotted-light} beam is an optical field whose locus of vanishing
intensity---a phase singularity---traces a closed knot $K$ in space. A conjecture
on such fields predicts that the discrete orbital-angular-momentum (OAM) values
the beam can carry are governed by the roots of the Alexander polynomial
$\Delta_K$ of the knot. For the family of $T(2,n)$ torus knots (the trefoil
$3_1 = T(2,3)$, the cinquefoil $5_1 = T(2,5)$, and their odd-$n$ successors), the
Alexander polynomial is the alternating geometric sum
$A_n(X) = 1 - X + X^2 - \cdots + X^{n-1}$. We complete the number-theoretic
picture of this family. Our central result is that, for every odd prime $p$, the
$T(2,p)$ Alexander polynomial is \emph{literally} the $2p$-th cyclotomic
polynomial, $A_p = \Phimm_{2p}$. From this we deduce that the complex roots are
\emph{exactly} the primitive $2p$-th roots of unity (no spurious roots); that the
degree---hence the number of OAM channels---is $\varphi(2p) = \varphi(p) = p-1$;
that the polynomial is irreducible over $\QQ$, so the spectrum is a single
Galois-conjugate orbit; that the knot determinant $|\Delta(-1)|$ equals $p$; and
that the knot is $3$-colorable iff $3 \mid p$, i.e.\ iff it is the trefoil. We
recover the classical determinants $3$ and $5$ uniformly, and contrast the
crystalline torus family with the figure-eight knot, whose Alexander roots
$\varphi^{\pm 2}$ (with $\varphi$ the golden ratio) lie off the unit circle.
\end{abstract}

\section{Introduction}

\subsection{Physical background}
Structured light beams can carry orbital angular momentum (OAM) through a helical
phase front. The axis of such a beam contains a \emph{phase singularity}: a curve
along which the field amplitude vanishes and the phase is undefined. Tailored
superpositions of paraxial modes can bend this singular curve into a closed loop
and even tie it into a nontrivial knot; experimentally realized knotted-light
fields have produced optical vortex lines shaped as trefoils. A guiding
conjecture posits that the admissible quantized OAM channels correspond to the
roots of the knot's Alexander polynomial. We take this bridge as motivation and
settle the algebra and number theory on the far side of it for the $T(2,n)$ torus
knots.

\subsection{Contributions}
Throughout we work with the alternating geometric sum
\[
A_n(X) = \sum_{i=0}^{n-1} (-X)^i = 1 - X + X^2 - \cdots + X^{n-1} \in \ZZ[X],
\]
the Alexander polynomial of $T(2,n)$ for odd $n$. We prove: the cyclotomic
identification $A_p = \Phimm_{2p}$; the exact root set; the channel count
$p-1$; irreducibility over $\QQ$; the determinant formula and $3$-colorability
criterion; and the crystalline/metallic contrast with the figure-eight.

\section{Definitions}

\begin{definition}[Alexander polynomial of $T(2,n)$]
For odd positive $n$, set $A_n(X) = \sum_{i=0}^{n-1}(-X)^i \in \ZZ[X]$, an
alternating sum of $n$ monomials with all coefficients $\pm 1$.
\end{definition}

\begin{definition}[Cyclotomic polynomial]
For $m \geq 1$, $\Phimm_m \in \ZZ[X]$ is the unique monic integer polynomial
whose complex roots are exactly the primitive $m$-th roots of unity,
$e^{2\pi i k/m}$ with $\gcd(k,m)=1$. It satisfies $X^m - 1 = \prod_{d \mid m}
\Phimm_d$, has degree $\varphi(m)$, and is irreducible over $\QQ$.
\end{definition}

\begin{definition}[Primitive roots as a set]
Write $\mu_m^{\ast} \subseteq \CC$ for the set of primitive $m$-th roots of
unity; then $|\mu_m^{\ast}| = \varphi(m)$ and
$\Phimm_m(X) = \prod_{\zeta \in \mu_m^{\ast}}(X-\zeta)$.
\end{definition}

\begin{definition}[Knot determinant]
$\det(K) = |\Delta_K(-1)|$.
\end{definition}

\begin{definition}[$3$-colorability]
A knot diagram is $3$-colorable if its arcs admit a coloring by three colors,
using more than one, such that at each crossing the incident arcs are all equal or
all distinct. A knot is $3$-colorable iff $3 \mid \det(K)$.
\end{definition}

\section{The master identity}

\begin{lemma}[Telescoping identity]\label{lem:master}
For every positive integer $n$, $(X+1)\,A_n(X) = X^n + 1$.
\end{lemma}
\begin{proof}
$A_n$ is a geometric series with ratio $-X$, so $(1+X)A_n(X) = 1 - (-X)^n$. For
odd $n$, $(-X)^n = -X^n$, giving $1 + X^n$.
\end{proof}

\begin{corollary}[Roots on the unit circle]\label{cor:circle}
Every complex root $\zeta$ of $A_n$ satisfies $\zeta^n = -1$ and $\zeta \neq -1$;
in particular $|\zeta| = 1$.
\end{corollary}
\begin{proof}
If $A_n(\zeta)=0$ then $(\zeta+1)A_n(\zeta) = \zeta^n+1 = 0$, so $\zeta^n=-1$ and
$|\zeta|=1$. As $A_n(-1)=n \neq 0$ (Lemma~\ref{lem:eval}), $\zeta \neq -1$.
\end{proof}

\section{Cyclotomic identification}

\begin{theorem}[Cyclotomic bridge]\label{thm:bridge}
For every odd prime $p$, $A_p(X) = \Phimm_{2p}(X)$ in $\ZZ[X]$.
\end{theorem}
\begin{proof}[Proof sketch]
By Lemma~\ref{lem:master}, $A_p(X) = (X^p+1)/(X+1)$. Writing
$X^{2p}-1 = \prod_{d \mid 2p}\Phimm_d$ and noting that the divisors of $2p$ (odd
prime $p$) are $1,2,p,2p$, cancellation of the factors indexed by divisors of $p$
(namely $1,p$) and by $2$ (the factor $\Phimm_2 = X+1$) leaves the single factor
$\Phimm_{2p}$. Both sides are monic of degree $p-1$ with identical roots, hence
equal. Directly, $A_3 = X^2-X+1 = \Phimm_6$ and
$A_5 = X^4-X^3+X^2-X+1 = \Phimm_{10}$.
\end{proof}

\begin{corollary}
$X^2 - X + 1 = \Phimm_6(X)$ and $X^4 - X^3 + X^2 - X + 1 = \Phimm_{10}(X)$.
\end{corollary}

\section{Exact root set}

\begin{theorem}[No spurious roots]\label{thm:roots}
For every odd prime $p$, the complex roots of $A_p$ are exactly the primitive
$2p$-th roots of unity $\mu_{2p}^{\ast}$, each of multiplicity one.
\end{theorem}
\begin{proof}
Over $\CC$, $A_p = \Phimm_{2p}$ by Theorem~\ref{thm:bridge}; the roots of
$\Phimm_{2p}$ are by definition exactly $\mu_{2p}^{\ast}$, each simple.
\end{proof}

\begin{corollary}
The roots of $A_3$ are the primitive sixth roots of unity $e^{\pm i\pi/3}$, and
those of $A_5$ are the primitive tenth roots $e^{\pm i\pi/5}, e^{\pm 3i\pi/5}$.
\end{corollary}

\section{Channel count}

\begin{theorem}[OAM channel count]\label{thm:count}
For every odd prime $p$,
$\deg A_p = \varphi(2p) = \varphi(p) = p-1 = |\mu_{2p}^{\ast}|$.
\end{theorem}
\begin{proof}
$\deg A_p = \deg \Phimm_{2p} = \varphi(2p)$. Since $\gcd(2,p)=1$,
$\varphi(2p) = \varphi(2)\varphi(p) = \varphi(p) = p-1$.
\end{proof}

\section{Irreducibility}

\begin{theorem}[Irreducibility over $\QQ$]\label{thm:irr}
For every odd prime $p$, $A_p$ is irreducible over $\QQ$.
\end{theorem}
\begin{proof}
$A_p = \Phimm_{2p}$ and cyclotomic polynomials are irreducible over $\QQ$.
\end{proof}

The OAM spectrum thus forms a single Galois-conjugate orbit: no proper nonempty
subset of the channels is the root set of a rational polynomial.

\section{Determinant and $3$-colorability}

\begin{lemma}[Evaluation at $-1$]\label{lem:eval}
For every odd $n$, $A_n(-1) = n$.
\end{lemma}
\begin{proof}
$A_n(-1) = \sum_{i=0}^{n-1}(-(-1))^i = \sum_{i=0}^{n-1} 1 = n$.
\end{proof}

\begin{theorem}[Torus determinant]\label{thm:det}
The determinant of $T(2,n)$ is $|A_n(-1)| = n$; the trefoil has determinant $3$
and the cinquefoil $5$.
\end{theorem}

\begin{theorem}[$3$-colorability criterion]\label{thm:color}
For an odd prime $p$, $T(2,p)$ is $3$-colorable ($3 \mid A_p(-1)$) iff $3 \mid p$
iff $p = 3$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:eval}, $3 \mid A_p(-1) \iff 3 \mid p$; primality gives $p=3$.
\end{proof}

More generally $T(2,p)$ is $q$-colorable iff $q = p$.

\section{The crystalline/metallic frontier}

\begin{proposition}[Kronecker dichotomy for reciprocal quadratics]
For $X^2 - bX + 1$ with $b \in \ZZ$, both roots lie on the unit circle iff
$b^2 < 4$, and both are real off the circle iff $b^2 > 4$.
\end{proposition}
\begin{proof}
The roots $\tfrac{b \pm \sqrt{b^2-4}}{2}$ have product $1$; for $b^2<4$ they are
conjugate of modulus $1$, for $b^2>4$ real reciprocal with one modulus $>1$.
\end{proof}

\begin{example}[The figure-eight knot]
The figure-eight $4_1$ has $\Delta_{4_1}(X) = X^2 - 3X + 1$, so $b=3$,
$b^2-4 = 5>0$, and the roots are $\varphi^{2} = \tfrac{3+\sqrt5}{2}$ and
$\varphi^{-2} = \tfrac{3-\sqrt5}{2}$, with $\varphi = \tfrac{1+\sqrt5}{2}$ the
golden ratio. They lie off the unit circle, making $4_1$ the smallest knot with a
metallic (non-crystalline) spectrum; its determinant is $|1+3+1| = 5$.
\end{example}

By Kronecker's theorem, a monic integer polynomial with all roots on the closed
unit disc (none zero) is a product of cyclotomics: ``all roots on the circle''
means ``product of cyclotomics'', the crystalline case, of which the torus family
are examples and the figure-eight is the minimal exception.

\section{Discussion and future directions}

The identification $A_p = \Phimm_{2p}$ turns individual root facts into a single
structural statement from which every downstream invariant follows. Future work:
(1) the composite factorization law $A_n = \prod_{d \mid 2n,\, d \nmid n}
\Phimm_d$; (2) a full Kronecker characterization of crystalline knots; (3) the
determinant-as-torsion-order interpretation with $q$-colorability for all primes
$q$; and (4) a uniform reciprocity law $t^{2g}\Delta(1/t) = \Delta(t)$ and
normalization $\Delta(1) = \pm 1$ from a Seifert-matrix axiomatization
$\Delta(t) = \det(V - tV^{\top})$.

\section{Conclusion}

For $T(2,p)$ at odd primes $p$, the Alexander polynomial is the $2p$-th
cyclotomic polynomial. This pins down the OAM spectrum: the channels are exactly
the primitive $2p$-th roots of unity, number $p-1$, form one Galois orbit, and the
determinant is $p$ with $3$-colorability isolating the trefoil. The figure-eight
and the golden ratio mark where the crystalline picture ends.

\end{document}

