from __future__ import annotations
from typing import List

def alexander_torus(n: int) -> List[int]:
    """Coefficients (low-degree-first) of A_n = 1 - X + X^2 - ... + X^{n-1}."""
    return [(-1) ** i for i in range(n)]

def poly_mul(a: List[int], b: List[int]) -> List[int]:
    out = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b):
            out[i + j] += ai * bj
    return out

def verify_master_identity(n: int) -> bool:
    """Check (X+1) * A_n(X) == X^n + 1 for odd n."""
    lhs = poly_mul(alexander_torus(n), [1, 1])
    rhs = [1] + [0] * (n - 1) + [1]
    return lhs == rhs

if __name__ == "__main__":
    for n in (3, 5, 7, 9, 11, 13):
        print(f"n={n:2d}  A_n={alexander_torus(n)}  identity holds: {verify_master_identity(n)}")

from __future__ import annotations
from math import gcd
from typing import List

def totient(n: int) -> int:
    r, m, p = n, n, 2
    while p * p <= m:
        if m % p == 0:
            while m % p == 0:
                m //= p
            r -= r // p
        p += 1
    if m > 1:
        r -= r // m
    return r

def poly_divide_exact(num: List[int], den: List[int]) -> List[int]:
    num = num[:]
    q = [0] * (len(num) - len(den) + 1)
    for i in range(len(q) - 1, -1, -1):
        c = num[i + len(den) - 1] // den[-1]
        q[i] = c
        for j, dj in enumerate(den):
            num[i + j] -= c * dj
    return q

def cyclotomic(m: int) -> List[int]:
    """Coefficients of Phi_m via X^m - 1 = prod_{d|m} Phi_d."""
    num = [-1] + [0] * (m - 1) + [1]
    for d in range(1, m):
        if m % d == 0:
            num = poly_divide_exact(num, cyclotomic(d))
    return num

def alexander_torus(n: int) -> List[int]:
    return [(-1) ** i for i in range(n)]

def identify(p: int) -> bool:
    """A_p == Phi_{2p} coefficient-wise (odd prime p)."""
    return alexander_torus(p) == cyclotomic(2 * p)

if __name__ == "__main__":
    for p in (3, 5, 7, 11, 13):
        print(f"p={p:2d}  A_p==Phi_2p: {identify(p)}  deg=phi(2p)=phi(p)=p-1={totient(2*p)}={p-1}")

from __future__ import annotations
import cmath, math
from typing import List

def alexander_torus(n: int) -> List[int]:
    return [(-1) ** i for i in range(n)]

def poly_eval(coeffs: List[int], x: complex) -> complex:
    acc = 0j
    for c in reversed(coeffs):
        acc = acc * x + c
    return acc

def primitive_roots(m: int) -> List[complex]:
    return [cmath.exp(2j * math.pi * k / m) for k in range(m) if math.gcd(k, m) == 1]

def spectrum_report(p: int) -> None:
    """Confirm roots of A_p are exactly the primitive 2p-th roots of unity."""
    coeffs = alexander_torus(p)
    prim = primitive_roots(2 * p)
    resid = max(abs(poly_eval(coeffs, z)) for z in prim)
    on_circle = all(abs(abs(z) - 1) < 1e-9 for z in prim)
    print(f"p={p}: channels={len(prim)} (=p-1={p-1}), "
          f"max|A_p(zeta)|={resid:.1e}, all on unit circle={on_circle}")
    for z in prim:
        print(f"    arg/pi = {cmath.phase(z)/math.pi:+.4f}  |z|={abs(z):.6f}")

if __name__ == "__main__":
    for p in (3, 5, 7):
        spectrum_report(p)

from __future__ import annotations
import math
from typing import List, Tuple

def poly_eval(coeffs: List[int], x: float) -> float:
    acc = 0.0
    for c in reversed(coeffs):
        acc = acc * x + c
    return acc

def torus_determinant(n: int) -> int:
    """Determinant of T(2,n): |A_n(-1)| = n."""
    coeffs = [(-1) ** i for i in range(n)]
    return abs(round(poly_eval(coeffs, -1.0)))

def figure_eight_roots() -> Tuple[float, float]:
    """Roots of X^2 - 3X + 1: the golden-ratio powers phi^{+/-2}."""
    b = 3.0
    d = math.sqrt(b * b - 4)
    return ((b + d) / 2, (b - d) / 2)

if __name__ == "__main__":
    for n in (3, 5, 7, 9, 11):
        det = torus_determinant(n)
        print(f"T(2,{n}): det={det}, 3-colorable={det % 3 == 0}, q-colorable for q={n}")
    r1, r2 = figure_eight_roots()
    phi = (1 + math.sqrt(5)) / 2
    print(f"figure-eight roots: {r1:.6f}, {r2:.6f}  (phi^2={phi**2:.6f}, phi^-2={phi**-2:.6f})")
    print(f"figure-eight off unit circle: {abs(r1) > 1}")

