from typing import List

def poly_divide_exact(num: List[int], den: List[int]) -> List[int]:
    """Exact quotient num / den for integer polynomials (den divides num)."""
    num = num[:]
    q = [0] * (len(num) - len(den) + 1)
    for i in range(len(q) - 1, -1, -1):
        c = num[i + len(den) - 1] // den[-1]
        q[i] = c
        for j, dj in enumerate(den):
            num[i + j] -= c * dj
    return q

def cyclotomic(m: int) -> List[int]:
    """Coefficients of Phi_m using X^m - 1 = prod_{d | m} Phi_d(X)."""
    num = [-1] + [0] * (m - 1) + [1]   # X^m - 1
    for d in range(1, m):
        if m % d == 0:
            num = poly_divide_exact(num, cyclotomic(d))
    return num

def alexander_is_cyclotomic(p: int) -> bool:
    """Test A_p == Phi_{2p} for an odd prime p."""
    a = [(-1) ** i for i in range(p)]
    return a == cyclotomic(2 * p)

